516	    /**
517	     * Test if the supplied tag is allowed by this safelist.
518	     * @param tag test tag
519	     * @return true if allowed
520	     */
521	    public boolean isSafeTag(String tag) {
522	        return tagNames.contains(TagName.valueOf(tag));
523	    }
524	
525	    /**
526	     * Test if the supplied attribute is allowed by this safelist for this tag.
527	     * <p>This method does not modify the input element or attribute.</p>
528	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
529	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
530	     * configured protocols when cleaning.</p>
531	     * @param tagName tag to consider allowing the attribute in
532	     * @param el element under test, to confirm protocol
533	     * @param attr attribute under test
534	     * @return true if allowed
535	     */
536	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
537	        TagName tag = TagName.valueOf(tagName);
538	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
539	
540	        Set<AttributeKey> okSet = attributes.get(tag);
541	        if (okSet != null && okSet.contains(key)) {
542	            if (protocols.containsKey(tag)) {
543	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
544	                // ok if not defined protocol; otherwise test. srcset URLs are tested per candidate in the Cleaner.
545	                return !attrProts.containsKey(key) || isSrcset(attr.getKey())
546	                    || (isSoundUrlValue(attr.getValue())
547	                        && isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key)));
548	            } else { // attribute found, no protocols defined, so OK
549	                return true;
550	            }
551	        }
552	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
553	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
554	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
555	            // if the input already has that exact value, treat it as safe
556	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
557	        }
558	        // no attributes defined for tag, try :all tag
559	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
560	    }
561	
562	    private String getProtocolValue(Element el, Attribute attr) {
563	        String value = el.absUrl(attr.getKey());
564	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
565	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
566	        return value;
567	    }
568	
569	    private static final Pattern BareScheme = Pattern.compile("^[a-zA-Z][a-zA-Z0-9+-.]*:$");
570	
571	    /**
572	     Tests if a single-value URL attribute value is structurally sound for protocol validation. Empty and
573	     whitespace-only values are left to the standard resolution rules. Otherwise, the value must not contain control
574	     characters or whitespace, and must not be a bare scheme (e.g. {@code "mailto:"}) with no content after the
575	     colon.
576	     */
577	    private static boolean isSoundUrlValue(String value) {
578	        if (StringUtil.isBlank(value)) return true; // blank values follow the standard resolution rules
579	        for (int i = 0, length = value.length(); i < length; i++) {
580	            char c = value.charAt(i);
581	            if (c <= 0x20 || c == 0x7f) return false; // control character or whitespace within the URL
582	        }
583	        return !BareScheme.matcher(value).matches();
584	    }
585	
586	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
587	        for (Protocol protocol : protocols) {
588	            String prot = protocol.toString();
589	
590	            if (prot.equals("#")) { // allows anchor links
591	                if (isValidAnchor(value)) {
592	                    return true;
593	                } else {
594	                    continue;
595	                }
596	            }
597	
598	            String lc = lowerCase(value);
599	            if (lc.startsWith(prot)
600	                && lc.length() > prot.length()
601	                && lc.charAt(prot.length()) == ':') {
602	                return true;
603	            }
604	        }
605	        return false;
606	    }
607	
608	    /**
609	     Tests if the attribute is {@code srcset} (case-insensitive), which holds a comma-separated list of image
610	     candidate URLs and so gets per-candidate cleaning in the {@link Cleaner}.
611	     */
612	    static boolean isSrcset(String attrKey) {
613	        return attrKey.equalsIgnoreCase(Srcset);
614	    }
615	
616	    /**
617	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
618	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
619	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
620	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
621	
622	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
623	     @param el the element the attribute is on, to resolve URLs against its base URI
624	     @param value the source srcset attribute value
625	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
626	     */
627	    String cleanSrcset(String tagName, Element el, String value) {
628	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
629	        StringBuilder sb = StringUtil.borrowBuilder();
630	
631	        int pos = 0, length = value.length();
632	        while (pos <= length) {
633	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
634	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
635	            // separators produce empty candidates, which are invalid.
636	            int start = pos, end = pos;
637	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
638	            boolean started = false; // seen non-whitespace content in this candidate
639	            while (end < length) {
640	                char c = value.charAt(end);
641	                if (c == ',') {
642	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
643	                        end++; // comma is part of the URL
644	                    else
645	                        break; // candidate separator
646	                } else {
647	                    if (isSrcsetSpace(c)) {
648	                        if (started) inUrl = false;
649	                    } else {
650	                        started = true;
651	                    }
652	                    end++;
653	                }
654	            }
655	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
656	            if (end >= length) break;
657	            pos = end + 1; // step past the separator comma
658	        }
659	
660	        if (sb.length() == 0) {
661	            StringUtil.releaseBuilderVoid(sb);
662	            return null;
663	        }
664	        return StringUtil.releaseBuilder(sb);
665	    }
666	
667	    /**
668	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
669	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
670	     */
671	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
672	        // trim ASCII whitespace from the candidate
673	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
674	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
675	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
676	
677	        // the URL is the leading run of non-whitespace
678	        int urlEnd = start;
679	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
680	        String url = value.substring(start, urlEnd);
681	        if (isOrphanDescriptor(url)) return; // a descriptor cannot stand in for the required URL
682	
683	        // an optional descriptor may follow, introduced by at least one ASCII space
684	        String descriptor = null;
685	        if (urlEnd < end) {
686	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
687	            int descStart = urlEnd;
688	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
689	            int descEnd = descStart;
690	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
691	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
692	            descriptor = value.substring(descStart, descEnd);
693	            if (!isValidSrcsetDescriptor(descriptor)) return;
694	        }
695	
696	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
697	
698	        if (sb.length() > 0) sb.append(", ");
699	        sb.append(url);
700	        if (descriptor != null) sb.append(' ').append(descriptor);
701	    }
702	
703	    /**
704	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
705	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
706	     other. Returns {@code null} when URLs are unrestricted.
707	     */
708	    private Set<Protocol> srcsetProtocols(TagName tag) {
709	        Set<AttributeKey> okSet = attributes.get(tag);
710	        if (okSet != null && okSet.contains(SrcsetKey)) {
711	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
712	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
713	        }
714	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
715	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
716	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
717	    }
718	
719	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
720	        // apply the same structural rules as for a single-value URL attribute: no control characters or inner
721	        // whitespace, and no bare scheme (e.g. "javascript:") with nothing after the colon
722	        if (!isSoundUrlValue(url)) return false;
723	        // the scheme must still be allowed after percent-decoding and stripping control characters, so that a
724	        // dangerous scheme cannot hide behind e.g. "java%73cript:", "%6Aavascript:", "%00javascript:", or leading
725	        // whitespace and control bytes
726	        if (!isSafeDecodedScheme(url, protocols)) return false;
727	
728	        String value = StringUtil.resolve(el.baseUri(), url);
729	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
730	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
731	        return isSafeProtocol(value, protocols);
732	    }
733	
734	    /**
735	     Checks the scheme of a candidate URL against the configured protocols, after undoing obfuscations that could hide
736	     a dangerous scheme from a naive prefix check. A real URL scheme is terminated by a <b>literal</b> colon, so the
737	     raw value is scanned for its first colon; percent-encoded bytes and ASCII control characters in the scheme run
738	     before that colon are normalized (e.g. {@code java%73cript:}, {@code %6Aavascript:}, and {@code java%00script:}
739	     all reveal {@code javascript:}). A value with no literal-colon scheme (a relative reference such as
740	     {@code x%3Ay.jpg} or an already-encoded {@code http%3a//host}) is left to the standard base-URI resolution
741	     rules, exactly like a single-value URL attribute. Never throws.
742	     */
743	    private static boolean isSafeDecodedScheme(String url, Set<Protocol> protocols) {
744	        int colon = url.indexOf(':');
745	        if (colon <= 0) return true; // no literal scheme separator: a relative / protocol-relative reference
746	
747	        String head = url.substring(0, colon);
748	        // the scheme run may only contain scheme characters or percent-escapes; anything else (e.g. a leading "//")
749	        // means this colon is not a scheme separator
750	        int length = head.length();
751	        boolean sawEscape = false;
752	        for (int i = 0; i < length; i++) {
753	            char c = head.charAt(i);
754	            if (c == '%') { sawEscape = true; continue; }
755	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
756	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
757	            if (!schemeChar) return true; // not a scheme; defer to base-URI resolution
758	        }
759	        if (!sawEscape) return true; // an unescaped scheme is checked by the normal resolved-URL protocol test
760	
761	        // decode the escaped bytes and drop any revealed control characters, then confirm a well-formed scheme
762	        String decoded = stripControlChars(percentDecode(head));
763	        if (decoded.isEmpty() || !isSchemeAlpha(decoded.charAt(0))) return true;
764	        for (int i = 0; i < decoded.length(); i++) {
765	            char c = decoded.charAt(i);
766	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
767	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
768	            if (!schemeChar) return true; // decoding revealed a non-scheme byte, so it is a relative reference
769	        }
770	
771	        String scheme = lowerCase(decoded);
772	        for (Protocol protocol : protocols) {
773	            String prot = protocol.toString();
774	            if (!prot.equals("#") && scheme.equals(prot)) return true; // the "#" pseudo-protocol never matches a scheme
775	        }
776	        return false;
777	    }
778	
779	    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL scheme. */
780	    private static String stripControlChars(String value) {
781	        int length = value.length();
782	        StringBuilder stripped = null;
783	        for (int i = 0; i < length; i++) {
784	            char c = value.charAt(i);
785	            if (c <= 0x1f || c == 0x7f) {
786	                if (stripped == null) {
787	                    stripped = new StringBuilder(length);
788	                    stripped.append(value, 0, i);
789	                }
790	            } else if (stripped != null) {
791	                stripped.append(c);
792	            }
793	        }
794	        return stripped != null ? stripped.toString() : value;
795	    }
796	
797	    /**
798	     Leniently decodes {@code %XX} percent-escapes to their (ISO-8859-1 mapped) character. Malformed or incomplete
799	     escapes are left as-is. Used only to reveal an obfuscated URL scheme, so decoding never throws and charset
800	     subtleties outside the ASCII scheme are irrelevant.
801	     */
802	    private static String percentDecode(String url) {
803	        int length = url.length();
804	        if (length < 3 || url.indexOf('%') == -1) return url;
805	        StringBuilder decoded = null;
806	        for (int i = 0; i < length; i++) {
807	            char c = url.charAt(i);
808	            if (c == '%' && i + 2 < length) {
809	                int hi = Character.digit(url.charAt(i + 1), 16);
810	                int lo = Character.digit(url.charAt(i + 2), 16);
811	                if (hi >= 0 && lo >= 0) {
812	                    if (decoded == null) {
813	                        decoded = new StringBuilder(length);
814	                        decoded.append(url, 0, i);
815	                    }
816	                    decoded.append((char) ((hi << 4) | lo));
817	                    i += 2;
818	                    continue;
819	                }
820	            }
821	            if (decoded != null) decoded.append(c);
822	        }
823	        return decoded != null ? decoded.toString() : url;
824	    }
825	
826	    /**
827	     * Tests if a candidate's first (and only) whitespace-delimited token is a descriptor with no URL in front of it,
828	     * rather than a relative URL. Such an orphan has the <i>shape</i> of a width or density descriptor: a lowercase
829	     * {@code w} or {@code x} suffix, an optional single leading sign, and a non-empty remaining run of only digits and
830	     * dots, e.g. {@code 2x}, {@code 100w}, {@code 1.5x}, {@code 0w}, {@code -1x}, {@code +1x}, {@code 1.x},
831	     * {@code .5x}, or {@code 1.5.2x}. This is a purely syntactic shape test (it does not require the number to be
832	     * valid), because a token that can only be read as a descriptor attempt supplies no decidable URL. A genuine
833	     * relative reference always carries something a descriptor number can never hold — another letter
834	     * ({@code 1e3x}, {@code 1X}, {@code 2x.jpg}), a path separator ({@code ../2x}), or an internal or second sign
835	     * ({@code 1-2x}, {@code ++2x}) — and so is never mistaken for an orphan.
836	     */
837	    private static boolean isOrphanDescriptor(String token) {
838	        int length = token.length();
839	        if (length < 2) return false; // a bare "w"/"x" is a possible relative reference, not a descriptor attempt
840	        char suffix = token.charAt(length - 1);
841	        if (suffix != 'w' && suffix != 'x') return false;
842	        int i = 0;
843	        if (token.charAt(0) == '+' || token.charAt(0) == '-') i++; // at most one, leading sign
844	        if (i == length - 1) return false; // just a sign and suffix (e.g. "+w"): a relative reference, not a number
845	        for (; i < length - 1; i++) {
846	            char c = token.charAt(i);
847	            boolean numberChar = (c >= '0' && c <= '9') || c == '.';
848	            if (!numberChar) return false; // a letter, separator, or internal sign marks a real URL
849	        }
850	        return true;
851	    }
852	
853	    /**
854	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
855	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
856	     Signs, exponents, a dot missing a side, and zero values are all invalid.
857	     */
858	    private static boolean isValidSrcsetDescriptor(String descriptor) {
859	        int length = descriptor.length();
860	        if (length < 2) return false;
861	        String number = descriptor.substring(0, length - 1);
862	        switch (descriptor.charAt(length - 1)) {
863	            case 'w': return isPositiveInteger(number);
864	            case 'x': return isPositiveNumber(number);
865	            default:  return false;
866	        }
867	    }
868	
869	    /** Tests if the value is all digits and greater than zero. */
870	    private static boolean isPositiveInteger(String number) {
871	        boolean nonZero = false;
872	        for (int i = 0, length = number.length(); i < length; i++) {
873	            char c = number.charAt(i);
874	            if (c < '0' || c > '9') return false;
875	            if (c != '0') nonZero = true;
876	        }
877	        return nonZero;
878	    }
879	
880	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
881	    private static boolean isPositiveNumber(String number) {
882	        int dot = number.indexOf('.');
883	        if (dot == -1) return isPositiveInteger(number);
884	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
885	        String integer = number.substring(0, dot);
886	        String fraction = number.substring(dot + 1);
887	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
888	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
889	    }
890	
891	    private static boolean isDigits(String value) {
892	        for (int i = 0, length = value.length(); i < length; i++) {
893	            char c = value.charAt(i);
894	            if (c < '0' || c > '9') return false;
895	        }
896	        return value.length() > 0;
897	    }
898	
899	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
900	    private static boolean isSrcsetSpace(char c) {
901	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
902	    }
903	
904	    /** Tests if the character is an ASCII letter, the required first character of a URL scheme. */
905	    private static boolean isSchemeAlpha(char c) {
906	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
907	    }
908	
909	    /**
910	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
911	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
912	     attribute.
913	     */
914	    boolean shouldAbsUrl(String tagName, String attrKey) {
915	        if (preserveRelativeLinks) return false;
916	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
917	    }
918	
919	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
920	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
921	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
922	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
923	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
924	        }
925	
926	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
927	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
928	
929	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
930	    }
931	
932	    private static boolean isValidAnchor(String value) {
933	        return value.startsWith("#") && !value.matches(".*\\s.*");
934	    }
935	
936	    /**
937	     Gets the Attributes that should be enforced for a given tag
938	     * @param tagName the tag
939	     * @return the attributes that will be enforced; empty if none are set for the given tag
940	     */
941	    public Attributes getEnforcedAttributes(String tagName) {
942	        Attributes attrs = new Attributes();
943	        TagName tag = TagName.valueOf(tagName);
944	        if (enforcedAttributes.containsKey(tag)) {
945	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
946	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
947	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
948	            }
949	        }
950	        return attrs;
951	    }
952	    
953	    // named types for config. All just hold strings, but here for my sanity.
954	
955	    static class TagName extends TypedValue {
956	        TagName(String value) {
957	            super(value);
958	        }
959	
960	        static TagName valueOf(String value) {
961	            return new TagName(Normalizer.lowerCase(value));
962	        }
963	    }
964	
965	    static class AttributeKey extends TypedValue {
966	        AttributeKey(String value) {
967	            super(value);
968	        }
969	
970	        static AttributeKey valueOf(String value) {
971	            return new AttributeKey(Normalizer.lowerCase(value));
972	        }
973	    }
974	
975	    static class AttributeValue extends TypedValue {
976	        AttributeValue(String value) {
977	            super(value);
978	        }
979	
980	        static AttributeValue valueOf(String value) {
981	            return new AttributeValue(value);
982	        }
983	    }
984	
985	    static class Protocol extends TypedValue {
986	        Protocol(String value) {
987	            super(value);
988	        }
989	
990	        static Protocol valueOf(String value) {
991	            return new Protocol(value);
992	        }
993	    }
994	
995	    abstract static class TypedValue {
996	        private final String value;
997	
998	        TypedValue(String value) {
999	            Validate.notNull(value);
1000	            this.value = value;
1001	        }
1002	
1003	        @Override
1004	        public int hashCode() {
1005	            return value.hashCode();
1006	        }
1007	
1008	        @Override
1009	        public boolean equals(Object obj) {
1010	            if (this == obj) return true;
1011	            if (obj == null || getClass() != obj.getClass()) return false;
1012	            TypedValue other = (TypedValue) obj;
1013	            return Objects.equals(value, other.value);
1014	        }
1015	
1016	        @Override
1017	        public String toString() {
1018	            return value;
1019	        }
1020	    }
1021	}
