package org.jsoup.safety;

import org.jsoup.internal.StringUtil;

/**
 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is a
 small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
 nesting of quotes, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
 declaration.

 <p>Declarations whose property is not a plain CSS identifier, or which are syntactically truncated (an unclosed string
 or comment, or a function with unbalanced parentheses), are dropped individually — surrounding safe declarations,
 other attributes, and the element's text are untouched. Each surviving declaration is scanned for external
 references ({@code url(...)}, the legacy {@code expression(...)} function, and an {@code @import} at-rule) and every
 reference found is checked against the safelist's URL rules; a single unsafe reference rejects only that declaration.
 Repeated separators and other degenerate input never throw and never cause following declarations to be joined into a
 rejected value.</p>

 <p>The cleaner is stateless and thread-safe; all per-value state lives in the local parse stack.</p>
 */
final class StyleCleaner {
    private final Safelist safelist;
    private final String tagName;
    private final org.jsoup.nodes.Element el;

    private StyleCleaner(Safelist safelist, String tagName, org.jsoup.nodes.Element el) {
        this.safelist = safelist;
        this.tagName = tagName;
        this.el = el;
    }

    /**
     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
     text of every declaration that survives.
     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
     */
    static String clean(Safelist safelist, String tagName, org.jsoup.nodes.Element el, String value) {
        return new StyleCleaner(safelist, tagName, el).clean(value);
    }

    private String clean(String value) {
        StringBuilder out = StringUtil.borrowBuilder();
        int length = value.length();
        int pos = 0;
        while (pos <= length) {
            int end = scanDeclaration(value, pos);
            if (end < 0) break; // a declaration opened but never closed (e.g. unclosed comment/string): rest is unsalvageable
            appendSafeDeclaration(value, pos, end, out);
            if (end == length) break;
            pos = end + 1; // step past the ';'
        }
        String result = out.length() == 0 ? null : StringUtil.releaseBuilder(out);
        if (result == null) StringUtil.releaseBuilderVoid(out);
        return result;
    }

    /**
     Finds the end index (exclusive) of the declaration beginning at {@code start}: the index of the terminating
     semicolon, or {@code length} for a final declaration. Semicolons nested in strings, comments, or functions are
     treated as content, as is any backslash-escaped character. Returns {@code -1} when an unterminated comment or
     string makes the declaration boundary undecidable; the caller drops the remainder in that case.
     */
    private int scanDeclaration(String value, int start) {
        int parenDepth = 0;
        int length = value.length();
        int i = start;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1; // unterminated string
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
                int commentEnd = value.indexOf("*/", i + 2);
                if (commentEnd < 0) return -1; // unterminated comment: no trustworthy boundary follows
                i = commentEnd + 2;
                continue;
            }
            if (c == '(') {
                parenDepth++;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--; // an unmatched ')' is plain content
            } else if (c == ';' && parenDepth == 0) {
                return i;
            }
            i++;
        }
        return length;
    }

    /** Returns the index of the unescaped closing quote, or {@code -1} if the string runs to the end of the value. */
    private int scanQuoted(String value, int from, char quote) {
        int length = value.length();
        for (int i = from; i < length; i++) {
            char c = value.charAt(i);
            if (c == '\\') { i++; continue; }
            if (c == quote) return i;
        }
        return -1;
    }

    /** Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}. */
    private void appendSafeDeclaration(String value, int start, int end, StringBuilder out) {
        int p = start;
        // property: a run of plain CSS identifier characters terminated by a colon, with optional CSS whitespace.
        // A custom property (--name) starts with a single '-'. Escapes, comments, and quotes are not valid here.
        int propEnd = p;
        boolean customProp = false;
        if (propEnd < end && value.charAt(propEnd) == '-') {
            propEnd++;
            if (propEnd < end && value.charAt(propEnd) == '-') {
                propEnd++;
                customProp = true;
            } else {
                return; // a single leading dash is not a valid property name
            }
        }
        while (propEnd < end && isIdent(value.charAt(propEnd))) propEnd++;
        int nameEnd = propEnd;
        if (!customProp && nameEnd == p) return; // no property name
        while (propEnd < end && isCssSpace(value.charAt(propEnd))) propEnd++;
        if (propEnd == end || value.charAt(propEnd) != ':') return; // missing ':' (e.g. empty or duplicate ';')

        if (!isSafeValue(value, propEnd + 1, end)) return;

        if (out.length() > 0) out.append(';');
        out.append(value, start, end);
    }

    /**
     Checks the value range {@code [from, end)} of a declaration: its parentheses must balance (outside strings and
     comments), and every external reference it contains must pass the safelist's URL rules.
     */
    private boolean isSafeValue(String value, int from, int end) {
        int parenDepth = 0;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return false; // defensive: scanDeclaration already bounded the declaration
                // url("...") is handled at the 'url(' level; a bare string elsewhere is inert but still scanned for
                // an obfuscated reference below via the unescaped substring.
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int commentEnd = value.indexOf("*/", i + 2);
                if (commentEnd < 0 || commentEnd >= end) return false; // nested unterminated comment
                i = commentEnd + 2;
                continue;
            }
            if (c == '(') { parenDepth++; i++; continue; }
            if (c == ')') {
                if (parenDepth == 0) return false; // unmatched ')' -> malformed declaration
                parenDepth--;
                i++;
                continue;
            }
            if (c == ';') return false; // cannot occur outside nesting; defensive
            i++;
        }
        if (parenDepth != 0) return false; // unclosed function

        // scan for references on a comment- and escape-aware view of the value
        return referencesAreSafe(value, from, end);
    }

    /**
     Walks the declaration value, skipping block comments (whose text is never parsed as CSS), and examining each
     function. {@code url(...)}, {@code @import} references, and the legacy script-bearing {@code expression(...)}
     function are resolved and checked; any other function is inert.
     */
    private boolean referencesAreSafe(String value, int from, int end) {
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int commentEnd = value.indexOf("*/", i + 2);
                i = (commentEnd < 0 || commentEnd >= end) ? end : commentEnd + 2; // comments are never declarations
                continue;
            }
            if (c == '@') {
                // the only at-rule valid in a declaration context is @import, and only as the (whitespace-prefixed)
                // start of the declaration value; anything "@import"-like elsewhere is invalid for inline style
                int nameStart = i + 1;
                if (matchesName(value, nameStart, end, "import"))
                    return isSafeImport(value, nameStart + 6, end);
                return false;
            }
            if (isIdentStart(c)) {
                int nameStart = i;
                while (i < end && isIdent(value.charAt(i))) i++;
                int j = i;
                while (j < end && isCssSpace(value.charAt(j))) j++;
                if (j < end && value.charAt(j) == '(') {
                    String name = value.substring(nameStart, i);
                    if (name.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
                    int argEnd = matchingParen(value, j + 1, end);
                    if (argEnd < 0) return false;
                    if (name.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
                    i = argEnd + 1;
                    continue;
                }
                continue;
            }
            i++;
        }
        return true;
    }

    /**
     Validates an {@code @import} in a declaration position. Its syntax is {@code @import [url(...) | string]
     [layer/media/supports...] ;}; only the reference itself is security-relevant.
     */
    private boolean isSafeImport(String value, int from, int end) {
        int i = from;
        while (i < end && isCssSpace(value.charAt(i))) i++;
        if (i < end && (value.charAt(i) == '"' || value.charAt(i) == '\'')) {
            int quoteEnd = scanQuoted(value, i + 1, value.charAt(i));
            if (quoteEnd < 0) return false;
            return safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quoteEnd)));
        }
        if (isIdentStart(value.charAt(i)) && matchesName(value, i, end, "url")) {
            int k = i + 3;
            while (k < end && isCssSpace(value.charAt(k))) k++;
            if (k < end && value.charAt(k) == '(') {
                int argEnd = matchingParen(value, k + 1, end);
                return argEnd >= 0 && isSafeUrlArgument(value, k + 1, argEnd);
            }
        }
        return false;
    }

    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
    private boolean isSafeUrlArgument(String value, int from, int end) {
        int i = from;
        while (i < end && isCssSpace(value.charAt(i))) i++;
        int j = end;
        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
        if (i == j) return false; // url() with no reference

        char first = value.charAt(i);
        String raw;
        if (first == '"' || first == '\'') {
            if (j <= i + 1 || value.charAt(j - 1) != first) return false; // mismatched quote
            raw = value.substring(i + 1, j - 1);
            // quotes may not be embedded (escaped or not) inside a quoted URL token
            for (int k = 0; k < raw.length(); k++) {
                char c = raw.charAt(k);
                if (c == '\\') { k++; continue; }
                if (c == first) return false;
            }
        } else {
            // unquoted: quotes and whitespace are not permitted bare, and the argument must be one token
            for (int k = i; k < j; k++) {
                char c = value.charAt(k);
                if (c == '\\') { k++; continue; }
                if (c == '"' || c == '\'' || c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f') return false;
            }
            raw = value.substring(i, j);
        }
        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
    }

    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
    private int matchingParen(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '(') depth++;
            else if (c == ')') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }

    private boolean matchesName(String value, int from, int end, String name) {
        int len = name.length();
        if (from + len > end) return false;
        for (int k = 0; k < len; k++) {
