package org.jsoup.safety;

import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Element;

/**
 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
 declaration.

 <p>Declarations with no recognizable property, an unclosed string or comment, unbalanced parentheses, or a forbidden
 or unverifiable external reference are dropped individually; surrounding safe declarations, other attributes, and
 the element's text are untouched. Each surviving declaration is scanned for references ({@code url(...)}, the legacy
 {@code expression(...)} function, and an {@code @import} at-rule) and every reference found is normalized through CSS
 unescaping and checked against the safelist's URL rules. Repeated separators and other degenerate input never throw
 and never cause following declarations to be joined into a rejected value.</p>

 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
 */
final class StyleCleaner {
    private final Safelist safelist;
    private final String tagName;
    private final Element el;

    private StyleCleaner(Safelist safelist, String tagName, Element el) {
        this.safelist = safelist;
        this.tagName = tagName;
        this.el = el;
    }

    /**
     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
     text of every declaration that survives.
     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
     */
    static String clean(Safelist safelist, String tagName, Element el, String value) {
        return new StyleCleaner(safelist, tagName, el).clean(value);
    }

    private String clean(String value) {
        StringBuilder out = StringUtil.borrowBuilder();
        int length = value.length();
        int pos = 0;
        while (pos < length) {
            int end = scanDeclaration(value, pos);
            if (end < 0) break; // an unterminated string or comment makes the remainder undecidable
            appendSafeDeclaration(value, pos, end, out);
            pos = end;
            if (pos < length && value.charAt(pos) == ';') pos++; // step past the separator
        }
        if (out.length() == 0) {
            StringUtil.releaseBuilderVoid(out);
            return null;
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Returns the index of the semicolon that terminates the declaration beginning at {@code start}, or {@code length}
     for a final declaration. Semicolons nested in strings, comments, or balanced functions are treated as content, as
     is any backslash-escaped character. Returns {@code -1} when an unterminated comment or string leaves no
     trustworthy boundary after {@code start}.
     */
    private int scanDeclaration(String value, int start) {
        int parenDepth = 0;
        int length = value.length();
        int i = start;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '(') {
                parenDepth++;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--; // an unmatched ')' is plain content here; validated below
            } else if (c == ';' && parenDepth == 0) {
                return i;
            }
            i++;
        }
        return length;
    }

    /** Returns the index of the unescaped closing quote, or {@code -1} if the string runs to the end of the value. */
    private int scanQuoted(String value, int from, char quote) {
        int length = value.length();
        for (int i = from; i < length; i++) {
            char c = value.charAt(i);
            if (c == '\\') { i++; continue; }
            if (c == quote) return i;
        }
        return -1;
    }

    /** Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}. */
    private void appendSafeDeclaration(String value, int start, int end, StringBuilder out) {
        int p = start;
        while (p < end && isCssSpace(value.charAt(p))) p++;
        int nameStart = p;

        // property: a plain CSS identifier, or a custom property (--name). Escapes, comments, and quotes are not
        // valid in a declaration name.
        boolean custom = false;
        if (p < end && value.charAt(p) == '-') {
            int dashes = 0;
            while (p < end && value.charAt(p) == '-' && dashes < 2) { p++; dashes++; }
            custom = dashes == 2;
            if (!custom) return; // a single leading dash is not a valid property name
        }
        if (p < end && isIdentStart(value.charAt(p))) {
            p++;
            while (p < end && isIdentChar(value.charAt(p))) p++;
        } else if (!custom) {
            return; // no property name
