    static String clean(Safelist safelist, String tagName, Element el, String value) {
        return new StyleCleaner(safelist, tagName, el).clean(value);
    }

    private String clean(String value) {
        StringBuilder out = StringUtil.borrowBuilder();
        int length = value.length();
        int pos = 0;
        while (pos < length) {
            int end = scanDeclaration(value, pos);
            if (end < 0) break; // an unterminated string or comment makes the remainder undecidable
            appendSafeDeclaration(value, pos, end, out);
            pos = end;
            if (pos < length && value.charAt(pos) == ';') pos++; // step past the separator
        }
        if (out.length() == 0) {
            StringUtil.releaseBuilderVoid(out);
            return null;
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Returns the index of the semicolon that terminates the declaration beginning at {@code start}, or {@code length}
     for a final declaration. Semicolons nested in strings, comments, or balanced functions are treated as content, as
     is any backslash-escaped character. Returns {@code -1} when an unterminated comment or string leaves no
     trustworthy boundary after {@code start}.
