            char c = value.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
