                parenDepth++;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--; // an unmatched ')' is plain content here; validated below
            } else if (c == ';' && parenDepth == 0) {
                return i;
            }
            i++;
        }
        return length;
