                i = close + 2;
                continue;
            }
            if (c == '(') { parenDepth++; i++; continue; }
            if (c == ')') {
                if (parenDepth == 0) return false; // unmatched ')'
                parenDepth--;
                i++;
                continue;
            }
            if (c == '@' && isAtStart(value, start, i)) {
                // only @import is legal in a declaration position, and it must reference a URL or string
                int after = i + 1;
