                return isSafeImport(value, after + 6, end);
            }
            if (isIdentStart(c)) {
                int nameStart = i;
                do { i++; } while (i < end && isIdentChar(value.charAt(i)));
                int j = i;
                while (j < end && isCssSpace(value.charAt(j))) j++;
