package org.jsoup.safety;

import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Element;

/**
 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
 declaration.

 <p>Declarations with no recognizable property, an unclosed string or comment, unbalanced parentheses, or a forbidden
 or unverifiable external reference are dropped individually; surrounding safe declarations, other attributes, and
 the element's text are untouched. Each surviving declaration is scanned for references ({@code url(...)}, the legacy
 {@code expression(...)} function, and an {@code @import} at-rule) and every reference found is normalized through CSS
 unescaping and checked against the safelist's URL rules. Repeated separators and other degenerate input never throw
 and never cause following declarations to be joined into a rejected value.</p>

 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
 */
final class StyleCleaner {
    private final Safelist safelist;
    private final String tagName;
    private final Element el;

    private StyleCleaner(Safelist safelist, String tagName, Element el) {
        this.safelist = safelist;
        this.tagName = tagName;
        this.el = el;
    }

    /**
     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
     text of every declaration that survives.
     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
     */
    static String clean(Safelist safelist, String tagName, Element el, String value) {
        return new StyleCleaner(safelist, tagName, el).clean(value);
    }

    private String clean(String value) {
        StringBuilder out = StringUtil.borrowBuilder();
        int length = value.length();
        int pos = 0;
        while (pos < length) {
            int end = scanDeclaration(value, pos);
            if (end < 0) break; // an unterminated string or comment makes the remainder undecidable
            appendSafeDeclaration(value, pos, end, out);
            pos = end;
            if (pos < length && value.charAt(pos) == ';') pos++; // step past the separator
        }
        if (out.length() == 0) {
            StringUtil.releaseBuilderVoid(out);
            return null;
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Returns the index of the semicolon that terminates the declaration beginning at {@code start}, or {@code length}
     for a final declaration. Semicolons nested in strings, comments, or balanced functions are treated as content, as
     is any backslash-escaped character. Returns {@code -1} when an unterminated comment or string leaves no
     trustworthy boundary after {@code start}.
     */
    private int scanDeclaration(String value, int start) {
        int parenDepth = 0;
        int length = value.length();
        int i = start;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '(') {
                parenDepth++;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--; // an unmatched ')' is plain content here; validated below
            } else if (c == ';' && parenDepth == 0) {
                return i;
            }
            i++;
        }
        return length;
    }

    /** Returns the index of the unescaped closing quote, or {@code -1} if the string runs to the end of the value. */
    private int scanQuoted(String value, int from, char quote) {
        int length = value.length();
        for (int i = from; i < length; i++) {
            char c = value.charAt(i);
            if (c == '\\') { i++; continue; }
            if (c == quote) return i;
        }
        return -1;
    }

    /** Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}. */
    private void appendSafeDeclaration(String value, int start, int end, StringBuilder out) {
        int p = start;
        while (p < end && isCssSpace(value.charAt(p))) p++;
        int nameStart = p;

        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
        boolean custom = false;
        if (p < end && value.charAt(p) == '-') {
            if (p + 1 < end && value.charAt(p + 1) == '-') {
                p += 2;
                custom = true;
                if (p >= end || !isNameChar(value.charAt(p))) return; // "--" alone is not a property name
                while (p < end && isNameChar(value.charAt(p))) p++;
            } else {
                if (p + 1 >= end || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
            }
        }
        if (!custom) {
            if (p >= end || !isIdentStart(value.charAt(p))) return; // no property name
            do { p++; } while (p < end && isIdentChar(value.charAt(p)));
        }
        while (p < end && isCssSpace(value.charAt(p))) p++;
        if (p == end || value.charAt(p) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
        p++; // step past ':'

        if (isDangerousProperty(value, nameStart, p - 1)) return; // known script-entry properties, regardless of value
        if (referencesAreSafe(value, p, end)) {
            if (out.length() > 0) out.append(';');
            out.append(value, start, end);
        }
    }

    /**
     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
     otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}.
     */
    private boolean isDangerousProperty(String value, int from, int colon) {
        int p = from;
        while (p < colon && isCssSpace(value.charAt(p))) p++;
        int q = colon;
        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
        String name = value.substring(p, q);
        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
    }

    /**
     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
     recognized exactly as in declaration splitting. Block comments are skipped (their text is never parsed as CSS);
     every {@code url(...)} argument, an {@code @import} reference, and the legacy {@code expression(...)} function is
     checked against the safelist. Unbalanced parentheses, an unterminated string or comment, or any failed reference
     check rejects the declaration.
     */
    private boolean referencesAreSafe(String value, int start, int end) {
        int parenDepth = 0;
        int i = start;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return false;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
                i = close + 2;
                continue;
            }
            if (c == '(') { parenDepth++; i++; continue; }
            if (c == ')') {
                if (parenDepth == 0) return false; // unmatched ')'
                parenDepth--;
                i++;
                continue;
            }
            if (c == '@' && isAtStart(value, start, i)) {
                // only @import is legal in a declaration position, and it must reference a URL or string
                int after = i + 1;
                if (!matchesName(value, after, end, "import")) return false;
                return isSafeImport(value, after + 6, end);
            }
            if (isIdentStart(c)) {
                int nameStart = i;
                do { i++; } while (i < end && isIdentChar(value.charAt(i)));
                int j = i;
                while (j < end && isCssSpace(value.charAt(j))) j++;
                if (j < end && value.charAt(j) == '(') {
                    String name = value.substring(nameStart, i);
                    int argEnd = matchingParen(value, j + 1, end);
                    if (argEnd < 0) return false;
                    if (name.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
                    if (name.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
                    i = argEnd + 1;
                    continue;
                }
                continue;
            }
            i++;
        }
        return parenDepth == 0;
    }

    /**
     An at-rule is only meaningful if nothing but whitespace (or comments, already skipped upstream) precedes it in
     the declaration value: an {@code @} inside e.g. {@code font-family: a@b} is plain text and must not be treated
     as an import.
     */
    private boolean isAtStart(String value, int from, int at) {
        for (int k = from; k < at; k++) {
            if (!isCssSpace(value.charAt(k))) return false;
        }
        return true;
    }

    /**
     Validates the reference of an {@code @import} at-rule: {@code @import "style.css"}, {@code @import url(...)},
     possibly followed by layer/media/supports conditions (which are ignored for safety once the reference passes).
     */
    private boolean isSafeImport(String value, int from, int end) {
        int i = from;
        while (i < end && isCssSpace(value.charAt(i))) i++;
        if (i == end) return false;
        char c = value.charAt(i);
        if (c == '"' || c == '\'') {
            int quoteEnd = scanQuoted(value, i + 1, c);
            if (quoteEnd < 0) return false;
            return safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quoteEnd)));
        }
        if (matchesName(value, i, end, "url")) {
            int k = i + 3;
            while (k < end && isCssSpace(value.charAt(k))) k++;
            if (k < end && value.charAt(k) == '(') {
                int argEnd = matchingParen(value, k + 1, end);
                return argEnd >= 0 && isSafeUrlArgument(value, k + 1, argEnd);
            }
        }
        return false;
    }

    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
    private boolean isSafeUrlArgument(String value, int from, int end) {
        int i = from;
        while (i < end && isCssSpace(value.charAt(i))) i++;
        int j = end;
        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
        if (i == j) return false; // url() with no reference

        char first = value.charAt(i);
        String raw;
        if (first == '"' || first == '\'') {
            if (j <= i + 1 || value.charAt(j - 1) != first) return false; // mismatched quote
            raw = value.substring(i + 1, j - 1);
            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
                char c = raw.charAt(k);
                if (c == '\\') { k++; continue; }
                if (c == first) return false;
            }
        } else {
            // an unquoted URL token is a single run: bare whitespace or quotes are syntax errors, not part of the URL
            for (int k = i; k < j; k++) {
                char c = value.charAt(k);
                if (c == '\\') { k++; continue; }
                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
            }
            raw = value.substring(i, j);
        }
        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
    }

    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
    private int matchingParen(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int quoteEnd = scanQuoted(value, i + 1, c);
                if (quoteEnd < 0) return -1;
                i = quoteEnd + 1;
                continue;
            }
            if (c == '(') depth++;
            else if (c == ')') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }

    private boolean matchesName(String value, int from, int end, String name) {
        int len = name.length();
        if (from + len > end) return false;
        for (int k = 0; k < len; k++) {
            char a = value.charAt(from + k);
            char b = name.charAt(k);
            if (a != b && a != Character.toUpperCase(b)) return false;
        }
        return true;
    }

    /**
     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
     CSS requirement to replace it.
     */
    static String unescape(String value) {
        if (value.indexOf('\\') == -1) return value;
        int length = value.length();
        StringBuilder sb = null;
        int i = 0;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\' && i + 1 < length) {
                if (sb == null) {
                    sb = new StringBuilder(length);
                    sb.append(value, 0, i);
                }
                int h = i + 1;
                int hexEnd = h;
                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
                if (hexEnd > h) {
                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
                    if (code != 0) sb.appendCodePoint(code);
                    i = hexEnd;
                } else {
                    sb.append(value.charAt(i + 1));
                    i += 2;
                }
                continue;
            }
            if (sb != null) sb.append(c);
            i++;
        }
        return sb != null ? sb.toString() : value;
    }

    private static boolean isCssSpace(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    private static boolean isHex(char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    private static boolean isIdentStart(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
    }

    private static boolean isIdentChar(char c) {
        return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-';
    }
}

