                    continue;
                }
                i = name[0];
                continue;
            }
            i++;
        }
        return true;
    }

    /**
     An at-rule is only meaningful if nothing but whitespace precedes it in the declaration value: an {@code @} inside
     e.g. {@code font-family: a@b} is plain text and must not be treated as an import.
     */
    private boolean isAtStart(String value, int from, int at) {
        for (int k = from; k < at; k++) {
            if (!isCssSpace(value.charAt(k))) return false;
        }
        return true;
    }

