private String clean(String value) {
    StringBuilder out = StringUtil.borrowBuilder();
    int length = value.length();
    int segStart = 0;
    int parenDepth = 0;
    boolean segmentBad = false; // an unclosed (newline-recovered) string occurred in this segment
    int i = 0;
    while (i < length) {
        char c = value.charAt(i);
        if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
            i += 2;
            continue;
        }
        if (c == '"' || c == '\'') {
            int[] quote = scanQuoted(value, i + 1, c);
            if (quote[1] == 0) { // ran off the end: no trustworthy declaration boundary follows
                appendSafeDeclaration(value, segStart, length, true, out);
                segStart = length;
                break;
            }
            if (quote[1] == 2) segmentBad = true; // bad-string recovery at a newline: this segment is malformed
            i = quote[0] + 1;
            continue;
        }
        if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
            int close = value.indexOf("*/", i + 2);
            if (close < 0) { // an unterminated comment swallows the remainder, which is never parsed as CSS
                appendSafeDeclaration(value, segStart, i, segmentBad, out);
                segStart = length;
                break;
            }
            i = close + 2;
            continue;
        }
        if (c == '(') {
            parenDepth++;
        } else if (c == ')') {
            if (parenDepth > 0) parenDepth--; // an unmatched ')' is plain content here; validated below
        } else if (c == ';' && parenDepth == 0) {
            appendSafeDeclaration(value, segStart, i, segmentBad, out);
            segStart = i + 1;
            segmentBad = false;
        }
        i++;
    }
    if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad, out);

    if (out.length() == 0) {
        StringUtil.releaseBuilderVoid(out);
        return null;
    }
    return StringUtil.releaseBuilder(out);
}

/**
 Scans a quoted string beginning just after its opening quote. Returns {@code [end, state]}: {@code end} is the
 * index to resume scanning from, and state is {@code 1} when the closing quote was found, {@code 2} when the
 * string was unterminated and recovered at a newline (the CSS bad-string rule, so declarations after the newline
 remain independently parseable), or {@code 0} when neither a quote nor a newline remains.
 */
private int[] scanQuoted(String value, int from, char quote) {
    int length = value.length();
    for (int i = from; i < length; i++) {
        char c = value.charAt(i);
        if (c == '\\') { i++; continue; }
        if (c == quote) return new int[] {i, 1};
        if (c == '\n') return new int[] {i, 2}; // bad-string recovery
    }
    return new int[] {length, 0};
}

