 @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
 */
private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
    if (structurallyBad) return;
    int p = start;
    while (p < end && isCssSpace(value.charAt(p))) p++;
    int nameStart = p;

    // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
    // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
    boolean custom = false;
    if (p < end && value.charAt(p) == '-') {
        if (p + 1 < end && value.charAt(p + 1) == '-') {
            p += 2;
            custom = true;
            if (p >= end || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
            while (p < end && isIdentChar(value.charAt(p))) p++;
        } else {
            if (p + 1 >= end || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
            p++; // let the ordinary identifier run consume the vendor-prefixed remainder
        }
    }
    if (!custom) {
        if (p >= end || !isIdentStart(value.charAt(p))) return; // no property name
        do { p++; } while (p < end && isIdentChar(value.charAt(p)));
    }
    while (p < end && isCssSpace(value.charAt(p))) p++;
    if (p == end || value.charAt(p) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
    p++; // step past ':'

    if (isDangerousProperty(value, nameStart, p - 1)) return; // known script-entry properties, regardless of value
    boolean safe = referencesAreSafe(value, p, end);
    if (safe && custom) // a custom property holds arbitrary free text, so scan its whole value as one string
        safe = freeTextIsSafe(value.substring(p, end));
    if (safe) {
        if (out.length() > 0) out.append(';');
        out.append(value, start, end);
    }
