import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class StyleProbe {
    static String clean(String html, String base, Safelist sl) {
        Document d = Jsoup.parseBodyFragment(html, base);
        return new Cleaner(sl).clean(d).body().html();
    }
    static void t(String name, String got, String want) {
        System.out.println((got.equals(want) ? "PASS " : "FAIL ") + name + "\n  got:  " + got + "\n  want: " + want);
    }
    public static void main(String[] a) {
        Safelist sl = Safelist.relaxed().addAttributes("div", "style");
        Safelist slp = new Safelist().addTags("div").addAttributes("div","style").preserveRelativeLinks(true);
        String base = "https://example.com/a/b";
        t("safe keep order", clean("<div style=\"color: red; FONT-SIZE :14px ;margin:0\">x</div>", base, sl),
          "<div style=\"color: red; FONT-SIZE :14px ;margin:0\">x</div>");
        t("font-family quote semicolon", clean("<div style=\"font-family: 'Calibri;'\">x</div>", base, sl),
          "<div style=\"font-family: 'Calibri;'\">x</div>");
        t("drop js url keep next", clean("<div style=\"color:red;background:url(javascript:alert(1));color:blue\">x</div>", base, sl),
          "<div style=\"color:red;color:blue\">x</div>");
        t("all dropped attr gone", clean("<div style=\"background:url(javascript:alert(1))\">x</div>", base, sl), "<div>x</div>");
        t("case mix", clean("<div style=\"background:URL(JAVASCRIPT:alert(1))\">x</div>", base, sl), "<div>x</div>");
        t("css escape scheme", clean("<div style=\"background:url(java\\73 cript:alert(1))\">x</div>", base, sl), "<div>x</div>");
        t("pct encoded", clean("<div style=\"background:url(java%73cript:alert(1))\">x</div>", base, sl), "<div>x</div>");
        t("protocol relative", clean("<div style=\"background:url(//evil.com/x.png)\">x</div>", base, sl),
          "<div style=\"background:url(//evil.com/x.png)\">x</div>");
        t("relative resolved kept", clean("<div style=\"background:url(img/x.png);color:red\">x</div>", base, sl),
          "<div style=\"background:url(img/x.png);color:red\">x</div>");
        t("relative no base dropped", clean("<div style=\"background:url(img/x.png);color:red\">x</div>", "", sl),
          "<div style=\"color:red\">x</div>");
        t("relative preserved (Jsoup.clean)", Jsoup.clean("<div style=\"background:url(img/x.png);color:red\">x</div>", slp),
          "<div style=\"background:url(img/x.png);color:red\">x</div>");
        t("safe http url kept verbatim", clean("<div style=\"background:url(http://example.com/x.png)\">x</div>", base, sl),
          "<div style=\"background:url(http://example.com/x.png)\">x</div>");
        t("malformed unclosed string", clean("<div style=\"color:red;font-family:'oops;color:blue\">x</div>", base, sl),
          "<div style=\"color:red;color:blue\">x</div>");
        t("unclosed paren", clean("<div style=\"color:red;background:url(x.png;color:blue\">x</div>", base, sl),
          "<div style=\"color:red;color:blue\">x</div>");
        t("dup semicolons", clean("<div style=\"color:red;;;color:blue\">x</div>", base, sl),
          "<div style=\"color:red;color:blue\">x</div>");
        t("comment benign", clean("<div style=\"color:red/* a;b */;color:blue\">x</div>", base, sl),
          "<div style=\"color:red/* a;b */;color:blue\">x</div>");
        t("comment smuggle", clean("<div style=\"color:red/* url(javascript:x) */;color:blue\">x</div>", base, sl),
          "<div style=\"color:red;color:blue\">x</div>");
        t("import", clean("<div style=\"@import url(https://example.com/x.css);color:red\">x</div>", base, sl),
          "<div style=\"@import url(https://example.com/x.css);color:red\">x</div>");
        t("import bad", clean("<div style=\"@import 'javascript:alert(1)';color:red\">x</div>", base, sl),
          "<div style=\"color:red\">x</div>");
        t("expression", clean("<div style=\"width:expression(alert(1));color:red\">x</div>", base, sl),
          "<div style=\"color:red\">x</div>");
        t("data denied", clean("<div style=\"background:url(data:text/html,<script>)\" >x</div>", base, sl), "<div>x</div>");
        t("vbscript", clean("<div style=\"background:url(vbscript:msgbox(1))\">x</div>", base, sl), "<div>x</div>");
        t("entity conceal", clean("<div style=\"background:url(&#0013;javascript:alert(1))\">x</div>", base, sl), "<div>x</div>");
        t("custom prop safe", clean("<div style=\"--foo: bar; color:red\">x</div>", base, sl),
          "<div style=\"--foo: bar; color:red\">x</div>");
        t("custom prop smuggled", clean("<div style=\"--foo: url(javascript:alert(1)); color:red\">x</div>", base, sl),
          "<div style=\"color:red\">x</div>");
        t("style disallowed removed", Jsoup.clean("<div style=\"color:red\">x</div>", Safelist.relaxed()), "<div>x</div>");
        t("moz-binding", clean("<div style=\"-moz-binding:url(https://example.com/x.xml#bind);color:red\">x</div>", base, sl),
          "<div style=\"color:red\">x</div>");
        t("stray close paren", clean("<div style=\"color:red);color:blue\">x</div>", base, sl),
          "<div style=\"color:blue\">x</div>");
    }
}
