/**
 Probes forward from just after a semicolon found while a function is open, to distinguish a semicolon that is
 * legitimately part of a balanced function (such as the {@code ;} in an unquoted {@code data:image/png;base64}
 * URL) from one following a function that never closes. Returns {@code true} when the currently open
 * parentheses all close (or the next declaration boundary is reached with everything balanced) before the value
 * ends.
 */
private boolean functionClosesAhead(String value, int from, int openDepth, int end) {
    int depth = openDepth;
    int i = from;
    while (i < end) {
        char c = value.charAt(i);
        if (c == '\\') { i += 2; continue; }
        if (c == '"' || c == '\'') {
            int[] quote = scanQuoted(value, i + 1, c);
            i = quote[1] == 2 ? quote[0] + 1 : quote[0] + (quote[1] == 1 ? 1 : 0);
            continue;
        }
        if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
            int close = value.indexOf("*/", i + 2);
            if (close < 0) break;
            i = close + 2;
            continue;
        }
        if (c == '(') depth++;
        else if (c == ')') { depth--; if (depth == 0) return true; }
        else if (c == ';' && depth == 0) return true; // reached the next declaration fully balanced
        i++;
    }
    return false;
}

