 * block comment, or the value of a custom property. Such text cannot introduce a declaration, but a rejected
 * reference must not survive in the emitted style, so every {@code url(...)}-shaped reference is extracted
 * (CSS-escapes normalized) and checked; the legacy {@code expression(...)} function is always rejected. A bare
 * scheme word such as {@code "javascript:alert(1)"} with no surrounding {@code url()} is inert in these contexts
 * and is left alone.
 */
private boolean freeTextIsSafe(String text) {
    int end = text.length();
    int i = 0;
    while (i < end) {
        char c = text.charAt(i);
        if (c == '\\') { i += 2; continue; }
        if (isIdentStart(c) || c == '-') {
            int[] name = readName(text, i, end);
            int j = name[0];
            while (j < end && isCssSpace(text.charAt(j))) j++;
            if (j < end && text.charAt(j) == '(') {
