import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;
import java.util.Random;
public class Fuzz3 {
    public static void main(String[] x) {
        Random r = new Random(99);
        String[] bases = {"", "https://example.com/base/", "http://x", "/relative/"};
        int n = 500000;
        for (int it = 0; it < n; it++) {
            Safelist sl = Safelist.relaxed().addAttributes(":all","style");
            if (r.nextBoolean()) sl.addProtocols(":all","style","data");
            int len = r.nextInt(30);
            StringBuilder sb = new StringBuilder();
            String chars = ";:()\"'/\\@*-#% \t\n\rurljava script:0123456789abcdefABCDEFxX.,&;q#tnru0";
            for (int k=0;k<len;k++) sb.append(chars.charAt(r.nextInt(chars.length())));
            String css = sb.toString();
            String html = "<p style=\"" + css.replace("\"", "&quot;") + "\">x</p>";
            String base = bases[r.nextInt(bases.length)];
            try {
                Document d = Jsoup.parseBodyFragment(html, base);
                Document c1 = new Cleaner(sl).clean(d);
                String out = c1.body().html();
                Document c2 = new Cleaner(sl).clean(Jsoup.parseBodyFragment(out, base));
                if (!out.equals(c2.body().html())) { System.out.println("IDEMPOT:\n"+css+"\n"+out+"\n"+c2.body().html()); return; }
                if (out.toLowerCase().contains("vbscript:")) { System.out.println("VBS LEAK: "+css+"\n"+out); return; }
            } catch (Throwable t) { System.out.println("EXC ["+css.replace("\n","\\n")+"]: "+t); t.printStackTrace(); return; }
        }
        System.out.println("FUZZ3 OK ("+n+" cases)");
    }
}
